SZGame2D.onStart(function __szProjectRun() {
  const __szProjectRunContext = window.__SZProjectLifecycle.begin(() => SZGame2D.restart());
  // Ao iniciar
  SZGame2D.setupStage(960, 600, "#a4c98a");
  const personagem = SZGame2D.createSprite({ x: 130, y: 310, w: 72, h: 72, image: "aventureiro" });
  const regador = SZGame2D.createSprite({ x: 390, y: 190, w: 60, h: 53, image: "regador-azul" });
  const flor = SZGame2D.createSprite({ x: 740, y: 265, w: 96, h: 120, image: "flor-fechada" });
  const fundoAviso = SZGame2D.createSprite({ x: 12, y: 12, w: 936, h: 38, color: "#264e45" });
  let aviso = "Recolha o regador e leve o personagem até a flor.";
  SZGame2D.enableClassicControls("directions");
  let temRegador = false;
  // Quando acontecer
  SZGame2D.onKey("r", () => {
    SZGame2D.restart();
  }, "eventoDeTecla");
  SZGame2D.onOverlap(() => personagem, () => regador, () => {
    SZGame2D.destroySprite(regador);
    temRegador = true;
    aviso = "Você pegou o regador! Agora vá até a flor.";
  }, "eventoDeContato");
  SZGame2D.onOverlap(() => personagem, () => flor, () => {
    if (temRegador) {
      SZGame2D.setImage(flor, "flor-aberta");
      aviso = "A flor abriu! Você fez o jardim florescer.";
    } else {
      aviso = "Busque o regador primeiro. A flor espera por você.";
    }
  }, "eventoDeContato_2");
  // Enquanto estiver rodando
  // O jogo roda 60 passos por segundo: cada volta desenha um "quadro" do filme.
  SZGame2D.gameLoop(function update() {
    SZGame2D.clear();
    SZGame2D.drawBackdrop(ctx, "jardim-acolhedor");
    SZGame2D.topDown(personagem, 5);
    SZGame2D.clampToScreen(personagem, ctx);
    SZGame2D.drawSprite(ctx, regador);
    SZGame2D.drawSprite(ctx, flor);
    SZGame2D.drawSprite(ctx, personagem);
    SZGame2D.drawSprite(ctx, fundoAviso);
    SZGame2D.drawLabel(ctx, aviso, 28, 38, "#ffffff", 19, "left");
    SZGame2D.drawLabel(ctx, "Setas: andar. R: nova partida.", 480, 585, "#264e45", 17, "center");
  }, "quadroDoJogo");
}, "__sz-project");

